import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");
const prdDir = path.join(root, "docs", "PRD");
const outFile = path.join(root, "app", "data", "prd-bundle.js");

const files = fs.readdirSync(prdDir).filter((name) => name.endsWith(".md"));
if (!files.length) {
  console.error("docs/PRD 下没有 .md 文件");
  process.exit(1);
}

const bundle = {};
for (const name of files) {
  const key = name.replace(/\.md$/i, "");
  const markdown = fs.readFileSync(path.join(prdDir, name), "utf8");
  if (markdown.includes("\uFFFD")) {
    console.error(`编码损坏（含替换字符）: ${name}`);
    process.exit(1);
  }
  bundle[key] = markdown.replace(/\r\n/g, "\n");
}

fs.mkdirSync(path.dirname(outFile), { recursive: true });
const body = `/* Generated by scripts/build-prd-bundle.mjs — do not edit by hand */\nwindow.__PRD_BUNDLE__ = ${JSON.stringify(bundle, null, 2)};\n`;
fs.writeFileSync(outFile, body, "utf8");
console.log(`wrote ${path.relative(root, outFile)} (${files.length} docs)`);
